location ~* \.pdf$ {
  add_header Accept-Ranges bytes;
  add_header Cache-Control "public, max-age=31536000, immutable";
  # Avoid gzipping already-compressed PDF streams so Content-Length stays exact for HTTP 206
  gzip off;
}

